    auto catalog=force_inventory_fixture::catalog();const auto art=profile(catalog);ForceInventory owner;check(owner.create(catalog),"owned stock");ChallengeForceSelection page;const auto token=request(owner,page,1000);SourceByteRngState seed{17,93},next=seed;ChallengeRandomAssembly assembly,duplicate;std::string error;
    const auto revision=owner.revision();check(assembly.begin(token,owner,art,seed,&error)&&!duplicate.begin(token,owner,art,seed,&error),"one assembly claim per accepted request");ChallengeRandomRoster roster;check(assembly.take(owner,&roster,&next)&&roster.current(owner)&&!token.valid(owner)&&roster.members().size()==3&&roster.source_spent()==425&&roster.nominal_cost()==425&&!roster.fallback(),"all fitting distinct box slots copied once, next RNG published");
    std::array<bool,kBoxBorgs> used{};for(const auto& member:roster.members()){check(member.origin==ChallengeRandomOrigin::Box&&member.source_slot<kBoxBorgs&&!used[member.source_slot]&&member.borg==owner.state()->box[member.source_slot].value,"native Borg/provenance copy and unique slot");used[member.source_slot]=true;}
    const auto accepted=roster;const auto accepted_rng=next;check(!assembly.take(owner,&roster,&next)&&!roster.current(owner)&&next==accepted_rng&&accepted.current(owner)&&owner.revision()==revision,"delivery once; failed take never rewinds caller RNG or mutates inventory");
