    check(owner.load_state(catalog,*state),"owned sparse warehouse");const auto warehouse_token=request(owner,page,1);ChallengeRandomAssembly warehouse;seed={255,255};next=seed;check(warehouse.begin(warehouse_token,owner,art,seed,&error)&&warehouse.trace().empty()&&warehouse.take(owner,&roster,&next)&&next==seed&&roster.fallback()&&roster.members()[0].origin==ChallengeRandomOrigin::Warehouse&&roster.members()[0].source_slot==1999&&roster.members()[0].borg==state->warehouse[1999]&&roster.source_spent()==0&&roster.nominal_cost()==250,"first special variant0 overrides earlier preferred Borgs, no budget clamp/RNG call");
    state->warehouse[1999]={};state->warehouse[2]=force_inventory_fixture::borg(0,1);check(owner.load_state(catalog,*state),"preferred tie fixture");const auto preferred_token=request(owner,page,1);ChallengeRandomAssembly preferred;check(preferred.begin(preferred_token,owner,art,seed,&error)&&preferred.take(owner,&roster,&next)&&roster.members()[0].source_slot==1,"lowest preferred variant, first stable tie");
    state=std::make_unique<ForceInventoryState>();check(owner.load_state(catalog,*state),"empty stock fixture");const auto builtin_token=request(owner,page,1);ChallengeRandomAssembly builtin;check(builtin.begin(builtin_token,owner,art,seed,&error)&&builtin.take(owner,&roster,&next)&&roster.members()[0].origin==ChallengeRandomOrigin::SourceDefault&&roster.members()[0].source_slot==0xffff&&roster.members()[0].borg.model==0x1001&&!roster.members()[0].borg.variant&&!roster.members()[0].borg.level&&!roster.members()[0].borg.acquired&&!roster.members()[0].borg.experience&&roster.source_spent()==0&&next==seed,"fresh source fallback, not a fabricated box slot or roster budget fit");
    //The low-byte modulo is deliberately biased for200 candidates, not a new
