    state=std::make_unique<ForceInventoryState>();state->box[0].value=force_inventory_fixture::borg(0);state->box[0].value.edits.modified=true;state->box[0].value.edits.values[0]=0;state->box[1].value=force_inventory_fixture::borg(2);state->box_count=2;check(owner.load_state(catalog,*state),"owned modified-cost state");auto edit_token=request(owner,page,75);ChallengeRandomAssembly base_cost;seed={0,0};check(base_cost.begin(edit_token,owner,art,seed,&error)&&base_cost.trace().size()==1&&base_cost.trace()[0].candidates==1&&base_cost.take(owner,&roster,&next)&&roster.members()[0].source_slot==1&&owner.state()->box[0].value.edits.modified,"authored source cost used; modified override neither changes pool nor loses provenance");
