    state=std::make_unique<ForceInventoryState>();state->warehouse[0]=force_inventory_fixture::borg(1);state->warehouse[0].edits.modified=true;state->warehouse[1]=force_inventory_fixture::borg(0);state->warehouse_count=2;check(owner.load_state(catalog,*state),"edited special fallback fixture");edit_token=request(owner,page,1);ChallengeRandomAssembly edited_fallback;check(!edited_fallback.begin(edit_token,owner,art,seed,&error)&&edited_fallback.status()==ChallengeRandomStatus::RejectedEdited&&owner.state()->warehouse[0].edits.modified,"edited special fallback refuses, not silently replaced by an unedited preferred Borg");
    check(owner.create(catalog),"stale fixture");const auto stale_token=request(owner,page,1000);ChallengeRandomAssembly stale;check(stale.begin(stale_token,owner,art,seed,&error)&&owner.rename_force(0,"NEW")==ForceChange::Applied&&!stale.take(owner,&roster,&next)&&!roster.current(owner),"late owner mutation cannot publish");
